/* GENERATED by tools (see make_tb_fast): fast full-system simulation of the SV25 firmware with the DSP present: the CPU-domain half of modem_core (186, DSP, cache, glue, codec)
   copied verbatim, one clock, flat zero-wait memories instead of the SDRAM and arbiter. Local firmware only: +flash= (CRC-patched image) +nvram= +rom= (DSP on-chip ROM).
   +ioptrace prints the 186's DSP-related port accesses; +icu the interrupt acknowledges / EOIs; +pcs=N a PC sample every N clocks. Not part of `make test`. */
`default_nettype none
`timescale 1ns/1ps
module tb_fast;
    logic clk = 0, clk_cpu_w;
    always #5 clk = ~clk;
    assign clk_cpu_w = clk;
    logic rst_n = 0;
    logic [19:0] pc186_o;
    logic        badop186_o;
    logic [15:0] pcdsp_o;
    logic        dac_valid_o;
    logic signed [15:0] dac_sample_o;
    logic        rom_loaded_c = 1'b1;
    logic        ee_en_c = 1'b0;
    logic [7:0]  ee_a_q = 8'h00;
    logic [15:0] ee_d_q = 16'h0000;
    logic        rx_sample_unused;
    logic [3:0]  xdc_ack;
    logic [63:0] xdc_rdata;
    logic [3:0]  xdc_req, xdc_we;
    logic [7:0]  xdc_be;
    logic [4*24-1:0] xdc_addr;
    logic [4*16-1:0] xdc_wdata;
    wire clk_cpu = clk;
    logic mwp, mwpm;
    logic [15:0] mwa, mwd;
    /* ---- clock enables: levels, not divided slots. A core runs every clk_cpu unless it waits for memory. */
    logic        xm_ready;
    logic        h_req, h_ack;
    logic        ce_dsp, ce_186;

    assign ce_dsp = xm_ready;
    assign ce_186 = 1'b1;

    /* ---- the 186: core + system (i186_top) with the DSP glue hooks */
    logic        h_wr, h_word, h_is_mmio;
    logic [19:0] h_addr;
    logic [15:0] h_wdata, h_rdata;
    logic        dte_tx_valid;
    logic [7:0]  dte_tx_byte;
    logic        dte_rx_valid;
    logic [7:0]  dte_rx_byte;
    logic        dte_line;
    logic        dsp_start_req, burst_valid;
    logic [63:0] burst_data;
    logic [63:0] hb_count;
    logic        glue_rd_commit, glue_wr_commit, glue_run, int0_set;
    logic        int0_hold_q, rx_hold_q;
    logic [7:0]  rx_hold_byte_q;
    logic [15:0] glue_rd_port, glue_wr_port;
    logic [7:0]  glue_wr_data, glue_rd_data;
    logic        unused_core_halted;
    logic [63:0] unused_cycles;
    logic [19:0] unused_badop_pc;
    logic [7:0]  unused_badop_op, unused_evt;
    logic [15:0] unused_h2d0, unused_relreg;

    i186_top u_186 (
        .clk               (clk_cpu),
        .ce_i              (ce_186),
        .rst_n             (rst_n),
        .model_tick_en     (1'b1),
        .nmi_req           (1'b0),
        .cyc_model         (1'b1),
        .ud_trap           (1'b1),
        .h_req             (h_req),
        .h_wr              (h_wr),
        .h_word            (h_word),
        .h_is_mmio         (h_is_mmio),
        .h_addr            (h_addr),
        .h_wdata           (h_wdata),
        .h_rdata           (h_rdata),
        .h_ack             (h_ack),
        .dte_tx_valid      (dte_tx_valid),
        .dte_tx_byte       (dte_tx_byte),
        .dte_rx_valid      (rx_hold_q),
        .dte_rx_byte       (rx_hold_byte_q),
        .line              (dte_line),
        .dsp_start_req     (dsp_start_req),
        .burst_valid       (burst_valid),
        .burst_data        (burst_data),
        .port_in_10        (8'h00),
        .port_in_12        (8'h9A),
        .port_in_14        (8'h44),
        .hw_idx            (4'd7),
        .ring_on           (1'b0),
        .hb_count          (hb_count),
        .hb_ticks          (64'd1),
        .p2pin_in          (8'h40),
        .ee_load_en        (ee_en_c),
        .ee_load_addr      (ee_a_q),
        .ee_load_data      (ee_d_q),
        .core_cycles       (unused_cycles),
        .core_halted       (unused_core_halted),
        .core_pc           (pc186_o),
        .core_badop        (badop186_o),
        .core_badop_pc     (unused_badop_pc),
        .core_badop_opcode (unused_badop_op),
        .dbg_icu           (dbg_icu_w),
        .dbg_evt           (unused_evt),
        .dbg_h2d0          (unused_h2d0),
        .dbg_pcb_relreg    (unused_relreg),
        .dsp_run_i         (glue_run),
        .glue_rd_data_i    (glue_rd_data),
        .glue_rd_port_o    (glue_rd_port),
        .glue_rd_commit_o  (glue_rd_commit),
        .glue_wr_commit_o  (glue_wr_commit),
        .glue_wr_port_o    (glue_wr_port),
        .glue_wr_data_o    (glue_wr_data),
        .int0_set_i        (int0_hold_q)
    );

    /* 186 memory (client 0) */
    logic        m186_req, m186_we;
    logic [1:0]  m186_be;
    logic [23:0] m186_addr;
    logic [15:0] m186_wdata;

    mem186 #(
        .BASE (24'h000000)
    ) u_mem186 (
        .clk        (clk_cpu),
        .rst_n      (rst_n),
        .h_req      (h_req),
        .h_wr       (h_wr),
        .h_word     (h_word),
        .h_is_mmio  (h_is_mmio),
        .h_addr     (h_addr),
        .h_wdata    (h_wdata),
        .h_rdata    (h_rdata),
        .h_ack      (h_ack),
        .rq_req_o   (m186_req),
        .rq_we_o    (m186_we),
        .rq_be_o    (m186_be),
        .rq_addr_o  (m186_addr),
        .rq_wdata_o (m186_wdata),
        .rq_ack_i   (xdc_ack[0]),
        .rq_rdata_i (xdc_rdata[15:0])
    );

    /* ---- the DSP: core + external memory cache + glue + codec */
    logic        dsp_rst_n;
    logic        xm_rd_en, xm_wr_en;
    logic [15:0] xm_raddr, xm_waddr, xm_wdata, xm_rdata;
    logic        pw_en, pw_ready;
    logic [15:0] pw_addr, pw_data;
    logic        xrq_req, xwq_req;
    logic [23:0] xrq_addr, xwq_addr;
    logic [15:0] xwq_wdata;

    c5x_xmem #(
        .BASE (24'h0C0000)
    ) u_xmem (
        .clk        (clk_cpu),
        .rst_n      (rst_n),
        .ce_i       (ce_dsp),
        .rd_en_i    (xm_rd_en),
        .raddr_i    (xm_raddr),
        .wr_en_i    (xm_wr_en),
        .waddr_i    (xm_waddr),
        .wdata_i    (xm_wdata),
        .rdata_o    (xm_rdata),
        .ready_o    (xm_ready),
        .hw_en_i    (pw_en),
        .hw_addr_i  (pw_addr),
        .hw_data_i  (pw_data),
        .hw_ready_o (pw_ready),
        .rq_req_o   (xrq_req),
        .rq_addr_o  (xrq_addr),
        .rq_ack_i   (xdc_ack[1]),
        .rq_rdata_i (xdc_rdata[31:16]),
        .wq_req_o   (xwq_req),
        .wq_addr_o  (xwq_addr),
        .wq_wdata_o (xwq_wdata),
        .wq_ack_i   (xdc_ack[2])
    );

    logic        io_req, io_rd, io_ack;
    logic [15:0] io_port, io_wdata, io_rdata;
    logic        dsp_int2, int2_hold_q;
    logic        aic_step, aic_ser_tick, aic_int3, frame_tick;
    logic [15:0] aic_ser_rx, mclk_n, rate_cps;
    logic        dxr_wr, instr_done, idle_dsp, rx_next;
    logic [15:0] dxr_wdata;
    logic [63:0] dsp_cycles, timer_exp;
    logic        pk_req;
    logic [23:0] pk_addr;
    logic signed [15:0] rx_sample;

    /* a DSP I/O request is taken once, at the first ce_dsp edge it is seen on (the core keeps io_req up for a further cycle after the ack) */
    logic io_seen_q, io_strobe;
    always_comb begin
        io_strobe = io_req && ce_dsp && !io_seen_q;
        io_ack    = io_req;
    end
    always_ff @(posedge clk_cpu) begin
        if (!io_req)
            io_seen_q <= 1'b0;
        else if (ce_dsp)
            io_seen_q <= 1'b1;
    end

    always_ff @(posedge clk_cpu) begin
        if (dsp_int2)
            int2_hold_q <= 1'b1;
        else if (ce_dsp)
            int2_hold_q <= 1'b0;
    end

    /* the DSP's INT1..INT3 inputs: INT2 on a host command, INT3 each codec frame; unused outputs below are observation ports of the co-sim */
    c5x_core #(
        .RESET_PC (16'h8000),
        .EXT_PMEM (1'b1)
    ) u_dsp (
        .clk             (clk_cpu),
        .ce_i            (ce_dsp),
        .rst_n           (dsp_rst_n),
        .xm_rd_en_o      (xm_rd_en),
        .xm_raddr_o      (xm_raddr),
        .xm_wr_en_o      (xm_wr_en),
        .xm_waddr_o      (xm_waddr),
        .xm_wdata_o      (xm_wdata),
        .xm_rdata_i      (xm_rdata),
        .step_i          (aic_step),
        .irq_i           ({6'd0, aic_int3, int2_hold_q, 1'b0}),
        .bio_i           (1'b0),
        .ivec_ind_i      ({16'h0068, 16'h0067, 16'h0066, 16'h0065, 16'h0064, 16'h0063, 16'h0062, 16'h0061, 16'h0060}),
        .ser_tick        (aic_ser_tick),
        .ser_rx          (aic_ser_rx),
        .xint_mode       (1'b1),
        .io_req          (io_req),
        .io_rd           (io_rd),
        .io_port         (io_port),
        .io_wdata        (io_wdata),
        .io_rdata        (io_rdata),
        .io_ack          (io_ack),
        .load_en         (1'b0),
        .load_pmem       (1'b0),
        .load_addr       (16'h0000),
        .load_data       (16'h0000),
        .dbg_en          (1'b0),
        .dbg_addr        (16'h0000),
        .dbg_rdata       (),
        .dbg_done        (),
        .dxr_wr          (dxr_wr),
        .dxr_wdata       (dxr_wdata),
        .timer_exp_cnt_o (timer_exp),
        .mem_wr_pulse    (mwp),
        .mem_wr_pmem     (mwpm),
        .mem_wr_addr     (mwa),
        .mem_wr_data     (mwd),
        .instr_done      (instr_done),
        .cycles_o        (dsp_cycles),
        .idle_o          (idle_dsp),
        .pc_o            (pcdsp_o)
    );

    dsp_glue u_glue (
        .clk             (clk_cpu),
        .rst_n           (rst_n),
        .rd_port_i       (glue_rd_port),
        .rd_data_o       (glue_rd_data),
        .rd_commit_i     (glue_rd_commit && ce_186),
        .wr_commit_i     (glue_wr_commit && ce_186),
        .wr_port_i       (glue_wr_port),
        .wr_data_i       (glue_wr_data),
        .run_o           (glue_run),
        .int0_set_o      (int0_set),
        .hb_count_o      (hb_count),
        .rom_loaded_i    (rom_loaded_c),
        .dsp_start_req_i (dsp_start_req && ce_186),
        .burst_valid_i   (burst_valid && ce_186),
        .burst_data_i    (burst_data),
        .io_req_i        (io_strobe),
        .io_rd_i         (io_rd),
        .io_addr_i       (io_port),
        .io_wdata_i      (io_wdata),
        .io_ack_o        (),
        .io_rdata_o      (io_rdata),
        .dsp_rst_n_o     (dsp_rst_n),
        .dsp_int2_o      (dsp_int2),
        .mclk_n_o        (mclk_n),
        .pw_en_o         (pw_en),
        .pw_addr_o       (pw_addr),
        .pw_data_o       (pw_data),
        .pw_ready_i      (pw_ready),
        .frame_tick_i    (frame_tick),
        .dsp_timer_exp_i (timer_exp[15:0]),
        .pk_req_o        (pk_req),
        .pk_addr_o       (pk_addr),
        .pk_ack_i        (xdc_ack[3]),
        .pk_rdata_i      (xdc_rdata[63:48])
    );

    aic u_aic (
        .clk          (clk_cpu),
        .rst_n        (rst_n),
        .ce_i         (ce_dsp),
        .cycles_i     (dsp_cycles[31:0]),
        .parked_i     (instr_done),
        .idle_i       (idle_dsp),
        .run_i        (dsp_rst_n),
        .step_o       (aic_step),
        .ser_tick_o   (aic_ser_tick),
        .ser_rx_o     (aic_ser_rx),
        .int3_o       (aic_int3),
        .dxr_wr_i     (dxr_wr),
        .dxr_wdata_i  (dxr_wdata),
        .mclk_n_i     (mclk_n),
        .dac_valid_o  (dac_valid_o),
        .dac_sample_o (dac_sample_o),
        .rx_next_o    (rx_next),
        .rx_sample_i  (rx_sample),
        .frame_tick_o (frame_tick),
        .rate_cps_o   (rate_cps)
    );

    /* line input: silence (the C model's noise floor is added in aic) */
    assign rx_sample = 16'sd0;

    logic [24:0] dbg_icu_w;
    logic mwp_dummy;
    assign dte_line = 1'b1;
    assign dte_rx_valid = 1'b0;
    assign dte_rx_byte = 8'h00;
    logic rx_hold_r = 1'b0; logic [7:0] rx_hold_b = 8'h00;
    assign rx_hold_q = rx_hold_r;
    assign rx_hold_byte_q = rx_hold_b;
    /* +typeat=<clock>: type "AT\r" (one byte every 400k clocks) on the DTE receive path, as the hold registers of modem_core present it */
    integer typeat = -1;
    initial begin
        void'($value$plusargs("typeat=%d", typeat));
        if (typeat >= 0) begin
            wait (cyc >= typeat);
            for (int ti = 0; ti < 3; ti = ti + 1) begin
                @(posedge clk); rx_hold_b <= (ti == 0) ? 8'h41 : (ti == 1) ? 8'h54 : 8'h0D; rx_hold_r <= 1'b1;
                @(posedge clk); while (!ce_186) @(posedge clk); rx_hold_r <= 1'b0;
                repeat (400000) @(posedge clk);
            end
        end
    end
    /* the client wiring of modem_core */
    assign xdc_req   = {pk_req, xwq_req, xrq_req, m186_req};
    assign xdc_we    = {1'b0, 1'b1, 1'b0, m186_we};
    assign xdc_be    = {2'b11, 2'b11, 2'b11, m186_be};
    assign xdc_addr  = {pk_addr, xwq_addr, xrq_addr, m186_addr};
    assign xdc_wdata = {16'h0000, xwq_wdata, 16'h0000, m186_wdata};

    /* flat memories: 186 1 MB as 512K words (0x40000.. read only = the flash image), the DSP's 64K-word program space at word address 0x0C0000 */
    logic [15:0] ram186 [0:524287];
    logic [15:0] pmem   [0:65535];
    logic [3:0] busy_q = 0;
    /* client i: ack one clock after the request is seen, data from the right memory */
    logic [3:0] ack_c;
    assign xdc_ack = ack_c;
    function automatic [15:0] rd_mem(input integer i, input [23:0] a);
        if (i == 1 || i == 2) rd_mem = pmem[a[15:0]];
        else rd_mem = ram186[a[18:0]];
    endfunction
    genvar gi;
    generate for (gi = 0; gi < 4; gi = gi + 1) begin : g_cl
        logic ack_d = 0;
        assign xdc_rdata[16*gi +: 16] = rd_mem(gi, xdc_addr[24*gi +: 24]);
        always @(posedge clk) begin
            ack_c[gi] <= 1'b0;
            ack_d <= ack_c[gi];
            if (xdc_req[gi] && !ack_d && !ack_c[gi]) begin
                ack_c[gi] <= 1'b1;
                if (xdc_we[gi]) begin
                    if (gi == 2) pmem[xdc_addr[24*gi +: 16]] <= xdc_wdata[16*gi +: 16];
                    else if (gi == 0 && xdc_addr[24*gi +: 24] < 24'h040000) begin
                        if (xdc_be[2*gi]) ram186[xdc_addr[24*gi +: 19]][7:0] <= xdc_wdata[16*gi +: 8];
                        if (xdc_be[2*gi+1]) ram186[xdc_addr[24*gi +: 19]][15:8] <= xdc_wdata[16*gi + 8 +: 8];
                    end
                end
            end
        end
    end endgenerate

    /* hold regs of modem_core */
    always_ff @(posedge clk) begin
        if (!rst_n) int0_hold_q <= 0;
        else if (int0_set) int0_hold_q <= 1; else if (ce_186) int0_hold_q <= 0;
    end

    reg [8*256-1:0] flash_path, nvram_path, rom_path;
    integer ff, n, i, clocks_max = 80000000, pcs_every = 0, cyc = 0, k;
    reg [7:0] fb [0:524287];
    reg [7:0] nb [0:511];
    reg [7:0] rb [0:16383];
    integer hist814 = 0, hist81ab = 0, hist81af = 0, hist81b2 = 0, hist8189 = 0, hist81a0 = 0, hist80d0 = 0;
    always @(posedge clk) if (rst_n && ce_dsp && instr_done) begin
        if (pcdsp_o == 16'h814D) hist814 <= hist814 + 1;
        if (pcdsp_o == 16'h81A0) hist81a0 <= hist81a0 + 1;
        if (pcdsp_o == 16'h81AB) hist81ab <= hist81ab + 1;
        if (pcdsp_o == 16'h81AF) hist81af <= hist81af + 1;
        if (pcdsp_o == 16'h81B2) hist81b2 <= hist81b2 + 1;
        if (pcdsp_o == 16'h8189) hist8189 <= hist8189 + 1;
        if (pcdsp_o == 16'h80D0) hist80d0 <= hist80d0 + 1;
    end
    integer ack_n = 0;
    integer cecnt_tb = 0;
    always @(posedge clk) if (rst_n && ce_186) cecnt_tb <= cecnt_tb + 1;
    integer dspmem_n = 0, dsppc_n = 0, frm_n = 0, st_hi = 0, xp = 0;
    always @(posedge clk) if (rst_n && dsp_seen) begin if (aic_ser_tick) st_hi <= st_hi + 1; if (u_dsp.mem_xint_pulse) xp <= xp + 1; end
    logic ifl_prev = 0; integer ifchg_n = 0;
    always @(posedge clk) if (rst_n && $test$plusargs("ifchg") && dsp_seen) begin
        ifl_prev <= u_186.u_core.ifl;
        if (u_186.u_core.ifl !== ifl_prev && ifchg_n < 60) begin ifchg_n <= ifchg_n + 1; $display("[tb] IF %b -> %b at pc %05h (instr start) ip %04h clock %0d state %0d", ifl_prev, u_186.u_core.ifl, pc186_o, u_186.u_core.ip, cyc, u_186.u_core.state); end
    end
    integer dsp_seen = 0, icu_n = 0, io_n = 0, dspio_n = 0;
    logic [16:0] lastw = 17'h1FFFF;
    always @(posedge clk) begin
        cyc <= cyc + 1;
        if (rst_n && glue_run && !dsp_seen) begin dsp_seen = 1; $display("[tb] DSP started (glue run) at clock %0d", cyc); end
        if (rst_n && pcs_every != 0 && cyc % pcs_every == 0) $display("[tb] clock %0d pc186 %05h pcdsp %04h icu=%h req=%b msk=%h isv=%b uart_sts0=%h rbuf0=%h", cyc, pc186_o, pcdsp_o, u_186.u_sys.dbg_icu, u_186.u_sys.req_r, u_186.u_sys.msk_r, u_186.u_sys.isv_present_r, u_186.u_sys.uart_sts[0], u_186.u_sys.uart_rbuf[0]);
        if (rst_n && $test$plusargs("icu") && icu_n < 600) begin
            if (u_186.u_sys.irq_ack && u_186.u_sys.icu_best_v) begin $display("[tb] ICU ack vec %02h pc %05h clock %0d  core: ifl %b irq_pending %b inhibit %b state %0d intstate_vec %02h tf %b halted %b", u_186.u_sys.irq_ack_vec, pc186_o, cyc, u_186.u_core.ifl, u_186.u_core.irq_pending, u_186.u_core.interrupt_inhibit, u_186.u_core.state, u_186.u_core.interrupt_vector, u_186.u_core.tf, u_186.u_core.halted); icu_n <= icu_n + 1; end
            if (u_186.u_sys.cmt_pcb_wr && u_186.u_sys.cmt_pcb_reg == 8'h02) begin $display("[tb] ICU eoi %04h pc %05h clock %0d", u_186.u_sys.cmt_pcb_val, pc186_o, cyc); icu_n <= icu_n + 1; end
        end
        if (rst_n && $test$plusargs("ioptrace") && io_n < 6000 && (dsp_seen || $test$plusargs("ioall"))) begin
            if (glue_wr_commit && ce_186 && !(lastw == {1'b1, glue_wr_port[7:0], glue_wr_data})) begin $display("[tb] 186 WR port %02h data %02h pc %05h clock %0d fl %04h", glue_wr_port[7:0], glue_wr_data, pc186_o, cyc, {4'hF, 1'b0, u_186.u_core.ifl, 10'b0}); io_n <= io_n + 1; lastw <= {1'b1, glue_wr_port[7:0], glue_wr_data}; end
            if (glue_rd_commit && ce_186 && !(lastw == {1'b0, glue_rd_port[7:0], glue_rd_data})) begin $display("[tb] 186 RD port %02h data %02h pc %05h clock %0d fl %04h", glue_rd_port[7:0], glue_rd_data, pc186_o, cyc, {4'hF, 1'b0, u_186.u_core.ifl, 10'b0}); io_n <= io_n + 1; lastw <= {1'b0, glue_rd_port[7:0], glue_rd_data}; end
        end
        if (rst_n && $test$plusargs("dspio") && io_strobe && dspio_n < 4000) begin
            dspio_n <= dspio_n + 1;
            if (io_rd) $display("[tb] DSP RD %02h -> %04h pc %04h clock %0d", io_port[7:0], io_rdata, pcdsp_o, cyc);
            else       $display("[tb] DSP WR %02h <- %04h pc %04h clock %0d", io_port[7:0], io_wdata, pcdsp_o, cyc);
        end
        if (rst_n && $test$plusargs("dspmem") && mwp && !mwpm && (mwa == 16'h0065 || mwa == 16'h006B || mwa == 16'h006C) && dspmem_n < 400) begin
            dspmem_n <= dspmem_n + 1; $display("[tb] DSP dm[%04h] <- %04h pc %04h clock %0d", mwa, mwd, pcdsp_o, cyc);
        end
        if (rst_n && $test$plusargs("dspack") && dsp_seen && u_dsp.ctrl_irq_ack_o != 0 && ack_n < 14) begin
            ack_n <= ack_n + 1; $display("[tb] DSP IRQ ACK %b ifr %h pc %04h clock %0d ar_wr %b rptc_ld %b brcr_ld %b wr_port_en %b sel %h", u_dsp.ctrl_irq_ack_o, u_dsp.addr_ifr, pcdsp_o, cyc, u_dsp.ctrl_ar_wr_en, u_dsp.ctrl_rptc_ld_en, u_dsp.ctrl_brcr_ld_en, u_dsp.wr_port_en, u_dsp.wr_port_sel);
        end
        if (rst_n && $test$plusargs("dsppc") && cyc > 6787400 && cyc < 6788100) begin
            if (u_dsp.ctrl_irq_ack_o != 0) $display("[tb] DSP IRQ ACK %b ifr %h imr? pc %04h clock %0d ar_wr %b rptc_ld %b brcr_ld %b", u_dsp.ctrl_irq_ack_o, u_dsp.addr_ifr, pcdsp_o, cyc, u_dsp.ctrl_ar_wr_en, u_dsp.ctrl_rptc_ld_en, u_dsp.ctrl_brcr_ld_en);
            if (ce_dsp && instr_done) $display("[tb] DSP instr done pc %04h ifr %h clock %0d", pcdsp_o, u_dsp.addr_ifr, cyc);
        end
        if (rst_n && $test$plusargs("frames") && frame_tick && frm_n < 40 && dsp_seen) begin
            frm_n <= frm_n + 1; $display("[tb] frame_tick clock %0d dsp_cycles %0d cps %0d pcdsp %04h ser_tick_high_clocks %0d xint_pulses %0d", cyc, dsp_cycles[31:0], rate_cps, pcdsp_o, st_hi, xp);
        end
        if (rst_n && dte_tx_valid && ce_186) $display("[tb] DTE byte %02h at clock %0d", dte_tx_byte, cyc);
    end
    always @(posedge clk) if (rst_n && $test$plusargs("dbg") && cyc > 49000 && cyc < 49030) $display("[tb] %0d pc %05h h_req %b ack %b m186_req %b ack0 %b we %b addr %06h ce186 %b", cyc, pc186_o, h_req, h_ack, m186_req, ack_c[0], m186_we, m186_addr, ce_186);
    initial begin
        void'($value$plusargs("clocks=%d", clocks_max));
        void'($value$plusargs("pcs=%d", pcs_every));
        if (!$value$plusargs("flash=%s", flash_path)) flash_path = "fw/SV25.flash.bin";
        if (!$value$plusargs("nvram=%s", nvram_path)) nvram_path = "fw/nvram.bin";
        if (!$value$plusargs("rom=%s", rom_path)) rom_path = "fw/c5x-onchip-rom-8k.bin";
        ff = $fopen(flash_path, "rb"); if (ff == 0) begin $display("FAIL: flash"); $finish; end
        n = $fread(fb, ff); $fclose(ff);
        for (i = 0; i < 524288; i = i + 1) ram186[i] = 16'hDEAD;
        for (i = 0; i < 262144; i = i + 1) ram186[19'h40000 + i] = {fb[2*i+1], fb[2*i]};
        for (i = 0; i < 65536; i = i + 1) pmem[i] = 16'h0000;
        ff = $fopen(rom_path, "rb"); if (ff == 0) begin $display("FAIL: rom"); $finish; end
        n = $fread(rb, ff); $fclose(ff);
        for (i = 0; i < 8192; i = i + 1) pmem[i] = {rb[2*i+1], rb[2*i]};
        ff = $fopen(nvram_path, "rb"); if (ff == 0) begin $display("FAIL: nvram"); $finish; end
        n = $fread(nb, ff); $fclose(ff);
        repeat (10) @(posedge clk);
        for (i = 0; i < 256; i = i + 1) begin @(posedge clk); ee_en_c <= 1; ee_a_q <= i[7:0]; ee_d_q <= {nb[2*i+1], nb[2*i]}; @(posedge clk); ee_en_c <= 0; end
        repeat (10) @(posedge clk); rst_n = 1;
        wait (cyc >= clocks_max);
        $display("[tb] DSP pc hits: 814D %0d 81A0 %0d 81AB %0d 81AF %0d 81B2 %0d 8189 %0d 80D0 %0d", hist814, hist81a0, hist81ab, hist81af, hist81b2, hist8189, hist80d0);
        $display("[tb] 186 enabled clocks %0d of %0d (%0d %%)", cecnt_tb, cyc, (cecnt_tb * 100) / cyc);
        $display("[tb] done at clock %0d pc186 %05h", cyc, pc186_o);
        $finish;
    end
endmodule
